}

std::string ImportNode::toString() const
{
  std::ostringstream stream;
  fs::path path((std::string)this->filename);

  stream << this->name();
  stream << "(file = " << this->filename;
  if (this->id) {
    stream << ", id = " << QuotedString(this->id.get());
  }
  if (this->layer) {
    stream << ", layer = " << QuotedString(this->layer.get());
  }
  stream << ", origin = [" << std::dec << this->origin_x << ", " << this->origin_y << "]";
  if (this->type == ImportType::SVG) {
    stream << ", dpi = " << this->dpi;
  }
  stream << ", scale = " << this->scale << ", center = " << (this->center ? "true" : "false")
         << ", convexity = " << this->convexity << ", " << this->discretizer
         << ", timestamp = " << fs_timestamp(path) << ")";

  return stream.str();
}

std::string LinearExtrudeNode::toString() const
{
  std::ostringstream stream;

  stream << this->name() << "(";
  double height = this->height.norm();
  stream << "height = " << height;
  if (height > 0) {
    Vector3d v = this->height / height;
    if (v[2] < 1) {
      stream << ", v = [ " << v[0] << ", " << v[1] << ", " << v[2] << "]";
    }
  }
  if (this->center) {
    stream << ", center = true";
  }
  if (this->has_twist) {
    stream << ", twist = " << this->twist;
  }
  if (this->has_slices) {
    stream << ", slices = " << this->slices;
  }
  if (this->has_segments) {
    stream << ", segments = " << this->segments;
  }

  if (this->scale_x != this->scale_y) {
    stream << ", scale = [" << this->scale_x << ", " << this->scale_y << "]";
  } else if (this->scale_x != 1.0) {
    stream << ", scale = " << this->scale_x;
  }

  if (!(this->has_slices && this->has_segments)) {
    stream << ", " << this->discretizer;
  }
  if (this->convexity > 1) {
    stream << ", convexity = " << this->convexity;
  }
  stream << ")";
  return stream.str();
}

std::string OffsetNode::toString() const
{
  std::ostringstream stream;

  bool isRadius = this->join_type == Clipper2Lib::JoinType::Round;
  auto var = isRadius ? "(r = " : "(delta = ";

  stream << this->name() << var << std::dec << this->delta;
  if (!isRadius) {
    stream << ", chamfer = " << (this->chamfer ? "true" : "false");
  }
  stream << ", " << this->discretizer << ")";

  return stream.str();
}

std::string ProjectionNode::toString() const
{
  return STR("projection(cut = ", (this->cut_mode ? "true" : "false"), ", convexity = ", this->convexity,
             ")");
}

std::string RenderNode::toString() const
{
  return STR(this->name(), "(convexity = ", convexity, ")");
}

std::string RoofNode::toString() const
{
  std::stringstream stream;

  stream << "roof(method = \"" << this->method << "\"" << ", " << discretizer
         << ", convexity = " << this->convexity << ")";

  return stream.str();
}

std::string RotateExtrudeNode::toString() const
{
  std::ostringstream stream;

  stream << this->name()
         << "("
            "angle = "
         << this->angle
         << ", "
            "start = "
         << this->start
         << ", "
            "convexity = "
         << this->convexity << ", " << discretizer << ")";

  return stream.str();
}

std::string SelectedObject::toString() const
{
  if (type == SelectionType::SELECTION_LINE) {
    return Vector3dtoString(p1) + " to " + Vector3dtoString(p2);
  }
  return Vector3dtoString(p1);
}

std::string SurfaceNode::toString() const
{
  std::ostringstream stream;
  fs::path path{static_cast<std::string>(this->filename)};  // gcc-4.6

  stream << this->name() << "(file = " << this->filename
         << ", center = " << (this->center ? "true" : "false")
         << ", invert = " << (this->invert ? "true" : "false")
         << ", "
            "timestamp = "
         << fs_timestamp(path) << ")";

  return stream.str();
}

std::string TextNode::toString() const
{
  return STR(name(), "(", this->params, ")");
}

std::string TransformNode::toString() const
{
  std::ostringstream stream;

  stream << "multmatrix([";
  for (int j = 0; j < 4; ++j) {
    stream << "[";
    for (int i = 0; i < 4; ++i) {
      stream << this->matrix(j, i);
      if (i != 3) stream << ", ";
    }
    stream << "]";
    if (j != 3) stream << ", ";
  }
  stream << "])";

  return stream.str();
}

